G = [[8]*11 for _ in range(17)]
# 5-outline rows1-5 cols4-8
for r in range(1,6):
    for c in range(4,9):
        G[r][c] = 5
# 9-box rows5-7 cols0-2
for r in range(5,8):
    for c in range(0,3):
        G[r][c] = 9
# fill interiors with 7
for r in range(2,5):
    for c in range(5,8):
        G[r][c] = 7
G[6][1] = 7
# verify against input
inp = [list(map(int, "8 8 8 8 8 8 8 8 8 8 8 8 8 8 8 5 5 5 5 5 8 8 8 8 8 5 8 8 8 5 8 8 8 8 8 5 8 8 8 5 8 8 8 8 8 5 8 8 8 5 8 8 9 9 9 8 5 5 5 5 5 8 8 9 8 9 8 8 8 8 8 8 8 8 9 9 9 8 8 8 8 8 8 8 8".split()))]
inp = [inp[0][i*11:(i+1)*11] for i in range(8)] + [[8]*11 for _ in range(9)]
ok = all((G[r][c]==inp[r][c]) or (inp[r][c]==8 and G[r][c]==7) for r in range(17) for c in range(11))
print("structure ok:", ok)
# check parity cells exactly: only interior cells changed
changed = [(r,c,inp[r][c],G[r][c]) for r in range(17) for c in range(11) if G[r][c]!=inp[r][c]]
print("changed:", changed)
for row in G: print(' '.join(map(str,row)))
